给定长度为 n 的整数数组 a[0..n−1]。若某元素出现的次数严格大于 n/2，则称其为该数组的主元素；主元素可能不存在。例如 a = (3, 3, 4, 2, 3, 3, 5, 3, 3) 中 3 出现 6 次 > 9/2，故 3 是主元素。设计算法：存在主元素时返回它，否则返回 −1，要求时间复杂度 O(n)、辅助空间 O(1)。
(1) 给出算法的基本设计思想，并说明哈希计数法与排序法为何不满足约束。（5分）
(2) 用 C 语言实现（须含对候选元素的验证），关键之处给出注释。（6分）
(3) 用抵消（配对删除）论证证明算法的正确性，并分析时间与空间复杂度。（4分）

int majority(int a[], int n) {
    int cand = a[0], cnt = 1;       /* 候选元素与其计数 */
    for (int i = 1; i < n; i++) {
        if (cnt == 0) {             /* 计数归零：改立新候选 */
            cand = a[i];
            cnt = 1;
        } else if (a[i] == cand) {
            cnt++;                  /* 同阵营：计数加 1 */
        } else {
            cnt--;                  /* 异阵营：一次抵消 */
        }
    }
    cnt = 0;                        /* 第二趟：验证候选 */
    for (int i = 0; i < n; i++)
        if (a[i] == cand) cnt++;
    return 2 * cnt > n ? cand : -1; /* 严格过半返回，否则 -1 */
}

github-408mock-mock07-42.stem:
无向带权图 G 有 6 个顶点 A、B、C、D、E、F，10 条边：(A,B,1)、(B,D,2)、(A,C,3)、(B,C,4)、(C,E,5)、(B,E,5)、(C,D,6)、(D,E,7)、(C,F,8)、(E,F,9)。
(1) 叙述 Kruskal 算法构造最小生成树的思想，说明并查集如何把「判环」加速到近似常数时间，并给出按秩合并与路径压缩的实现要点。（4分）
(2) 给出 Kruskal 算法的 C 语言实现（含并查集），函数返回最小生成树的权值。（4分）
(3) 列出按边权递增处理每条边的取舍过程，给出最小生成树及其权值；再用「换边法」判断该图的最小生成树是否唯一，若不唯一，给出另一棵。（2分）

typedef struct { int u, v, w; } Edge;   /* 边：两端点与权值 */

int parent[6], rnk[6];

void initSet() {
    for (int i = 0; i < 6; i++) { parent[i] = i; rnk[i] = 0; }
}

int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]); /* 路径压缩 */
    return parent[x];
}

int unionSet(int x, int y) {
    int rx = find(x), ry = find(y);
    if (rx == ry) return 0;            /* 同属一棵树：加入会成环 */
    if (rnk[rx] < rnk[ry]) { int t = rx; rx = ry; ry = t; }
    parent[ry] = rx;                   /* 按秩合并：矮树挂高树 */
    if (rnk[rx] == rnk[ry]) rnk[rx]++;
    return 1;
}

int cmpEdge(const void *a, const void *b) {
    return ((Edge *)a)->w - ((Edge *)b)->w;
}

/* e[] 为输入边集（m 条），t[] 返回选中的生成树边，返回生成树权值，图不连通返回 -1 */
int kruskal(Edge e[], int m, Edge t[]) {
    qsort(e, m, sizeof(Edge), cmpEdge);
    initSet();
    int k = 0, total = 0;
    for (int i = 0; i < m && k < 5; i++)
        if (unionSet(e[i].u, e[i].v)) { t[k++] = e[i]; total += e[i].w; }
    return (k == 5) ? total : -1;
}

github-408mock-mock07-45.stem:
桌上有一只水果篮，容量为 3 个水果，且篮中苹果最多 2 个、橙子最多 2 个。爸爸专门向篮中放苹果，妈妈专门向篮中放橙子，女儿专吃苹果，儿子专吃橙子。篮子一次只能被一人访问（放入/取出操作必须互斥），只有篮中有苹果时女儿才能取，只有篮中有橙子时儿子才能取。
(1) 定义所需的信号量，给出每个信号量的含义与初值，并说明初值的推算依据。（3分）
(2) 用记录型信号量的 P、V 操作写出爸爸、妈妈、女儿、儿子四个进程的同步算法（伪代码）。（4分）
(3) 分析该算法是否存在死锁；若去掉「每种水果上限 2 个」的限制（只保留总量 3），会出现什么问题？（1分）

semaphore plate = 3;      /* 篮中还可放入的水果数（容量余额） */
semaphore apple = 0;      /* 篮中现有苹果数 */
semaphore orange = 0;     /* 篮中现有橙子数 */
semaphore appleCap = 2;   /* 苹果上限余额：还可再放入的苹果数 */
semaphore orangeCap = 2;  /* 橙子上限余额：还可再放入的橙子数 */
semaphore mutex = 1;      /* 篮子的互斥访问 */

dad() {                          /* 爸爸放苹果 */
    while (1) {
        prepare_apple();
        P(appleCap);             /* 先占苹果名额，保证篮中苹果不超过 2 */
        P(plate);                /* 再占篮子容量 */
        P(mutex);
        put_apple();
        V(mutex);
        V(apple);                /* 苹果数加 1，可能唤醒女儿 */
    }
}

mom() {                          /* 妈妈放橙子 */
    while (1) {
        prepare_orange();
        P(orangeCap);
        P(plate);
        P(mutex);
        put_orange();
        V(mutex);
        V(orange);
    }
}

daughter() {                     /* 女儿取苹果 */
    while (1) {
        P(apple);                /* 等篮中出现苹果 */
        P(mutex);
        take_apple();
        V(mutex);
        V(appleCap);             /* 归还苹果名额 */
        V(plate);                /* 归还篮子容量，可能唤醒父母 */
        eat_apple();
    }
}

son() {                          /* 儿子取橙子 */
    while (1) {
        P(orange);
        P(mutex);
        take_orange();
        V(mutex);
        V(orangeCap);
        V(plate);
        eat_orange();
    }
}

